  it('accepts faq content type', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, contentType: 'faq' }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.contentType).toBe('faq') })
  it('accepts service_page content type', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, contentType: 'service_page' }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.contentType).toBe('service_page') })
  it('accepts zh-hant language', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, language: 'zh-hant' }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.language).toBe('zh-hant') })
  it('normalizes brief title with NFKC and whitespace rules', () => { const result = buildGeoFlowRequest(validRequestDraft); expect(result.ok).toBe(true); if (result.ok) expect(result.value.brief.title).toBe('NFKC Article Title') })
  it('normalizes brief audience with trim and whitespace rules', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, audience: '  Content   operators  ' } }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.brief.audience).toBe('Content operators') })
  it('preserves normalized goal order', () => { const result = buildGeoFlowRequest(validRequestDraft); expect(result.ok).toBe(true); if (result.ok) expect(result.value.brief.goals).toEqual(['Answer the question', 'Support review']) })
  it('preserves normalized constraint order', () => { const result = buildGeoFlowRequest(validRequestDraft); expect(result.ok).toBe(true); if (result.ok) expect(result.value.brief.constraints).toEqual(['Use approved evidence', 'Keep the answer precise']) })
  it('allows an empty constraints array', () => { const result = buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, constraints: [] } }); expect(result.ok).toBe(true); if (result.ok) expect(result.value.brief.constraints).toEqual([]) })
