  it('rejects duplicate normalized constraints', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, constraints: ['Rule', ' Rule '] } }), 'INVALID_INPUT') })
  it('rejects an overlong brief title', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, title: 'x'.repeat(301) } }), 'LIMIT_EXCEEDED') })
  it('rejects an overlong brief audience', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, audience: 'x'.repeat(301) } }), 'LIMIT_EXCEEDED') })
  it('rejects an overlong goal item', () => { expectFailure(buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, goals: ['x'.repeat(501)] } }), 'LIMIT_EXCEEDED') })
