  it('brief audience mutation changes briefFingerprint', () => { const a = buildGeoFlowRequest(validRequestDraft); const b = buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, audience: 'Different audience' } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.briefFingerprint).not.toBe(b.value.briefFingerprint) })
  it('brief goal mutation changes briefFingerprint', () => { const a = buildGeoFlowRequest(validRequestDraft); const b = buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, goals: ['Different goal'] } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.briefFingerprint).not.toBe(b.value.briefFingerprint) })
  it('content type mutation changes briefFingerprint', () => { const a = buildGeoFlowRequest(validRequestDraft); const b = buildGeoFlowRequest({ ...validRequestDraft, contentType: 'faq' }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.briefFingerprint).not.toBe(b.value.briefFingerprint) })
  it('language mutation changes briefFingerprint', () => { const a = buildGeoFlowRequest(validRequestDraft); const b = buildGeoFlowRequest({ ...validRequestDraft, language: 'zh-hant' }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.briefFingerprint).not.toBe(b.value.briefFingerprint) })
  it('brief constraint mutation changes requestFingerprint', () => { const a = buildGeoFlowRequest(validRequestDraft); const b = buildGeoFlowRequest({ ...validRequestDraft, brief: { ...validRequestDraft.brief, constraints: ['Different constraint'] } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.requestFingerprint).not.toBe(b.value.requestFingerprint) })
