  it('rejects revision context without parentContentHash', () => { expectFailure(buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, parentContentHash: undefined } }), 'INVALID_HASH') })
