  it('rejects revision context without instructions', () => { expectFailure(buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, instructions: undefined } }), 'INVALID_INPUT') })
  it('rejects an overlong revision instruction', () => { expectFailure(buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, instructions: 'x'.repeat(4001) } }), 'LIMIT_EXCEEDED') })
  it('revision parentDraftId mutation changes requestFingerprint', () => { const a = buildGeoFlowRequest(validRevisionDraft); const b = buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, parentDraftId: 607 } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.requestFingerprint).not.toBe(b.value.requestFingerprint) })
  it('revision parentContentHash mutation changes requestFingerprint', () => { const a = buildGeoFlowRequest(validRevisionDraft); const b = buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, parentContentHash: HASH_B } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.requestFingerprint).not.toBe(b.value.requestFingerprint) })
  it('revision review ID mutation changes requestFingerprint', () => { const a = buildGeoFlowRequest(validRevisionDraft); const b = buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, changeRequestReviewId: 708 } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.requestFingerprint).not.toBe(b.value.requestFingerprint) })
  it('revision instructions mutation changes requestFingerprint', () => { const a = buildGeoFlowRequest(validRevisionDraft); const b = buildGeoFlowRequest({ ...validRevisionDraft, revisionContext: { ...validRevisionDraft.revisionContext!, instructions: 'Different instructions' } }); expect(a.ok && b.ok).toBe(true); if (a.ok && b.ok) expect(a.value.requestFingerprint).not.toBe(b.value.requestFingerprint) })
