  it('rejects a throwing request proxy', () => { const input = new Proxy({ ...validRequestDraft }, { get(_target, property) { if (property === 'brief') throw new Error('proxy'); return Reflect.get(_target, property) } }); expectFailure(buildGeoFlowRequest(input), 'INVALID_INPUT') })
