  it('rejects a response brief fingerprint mismatch', () => { expectFailure(validateGeoFlowResponse(responseWith({ draftIdentity: { ...validResponse.draftIdentity, briefFingerprint: HASH_B } }), validRequest), 'BRIEF_FINGERPRINT_MISMATCH') })
  it('rejects an external article identity mismatch', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalArticleKey: 'article-other', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'article-other' } }), validRequest), 'IDENTITY_MISMATCH') })
  it('rejects a response content type mismatch', () => { expectFailure(validateGeoFlowResponse(responseWith({ contentArtifact: artifactWith({ contentType: 'faq' }) }), validRequest), 'IDENTITY_MISMATCH') })
