  it('accepts exact bodyMarkdown bytes without whitespace rewrite', () => { const body = '  exact\nmarkdown  '; const result = validateGeoFlowResponse(responseWith({ contentArtifact: artifactWith({ bodyMarkdown: body, bodyHash: sha256(body) }) }), validRequest); expect(result.ok).toBe(true); if (result.ok && (result.value.status === 'draft_ready' || result.value.status === 'review_required')) expect(result.value.contentArtifact.bodyMarkdown).toBe(body) })
  it('rejects bodyMarkdown over 200000 UTF-8 bytes', () => { const body = 'x'.repeat(200001); expectFailure(validateGeoFlowResponse(responseWith({ contentArtifact: artifactWith({ bodyMarkdown: body, bodyHash: sha256(body) }) }), validRequest), 'LIMIT_EXCEEDED') })
  it('rejects a response uppercase body hash', () => { expectFailure(validateGeoFlowResponse(responseWith({ contentArtifact: artifactWith({ bodyHash: BODY_HASH.toUpperCase() }) }), validRequest), 'INVALID_HASH') })
