describe('GEOFlow generation contract V1 — combined status events and lineage', () => {
  it('accepts initial queued event without previous state', () => { const result = validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }); expect(result.ok).toBe(true) })
  it('rejects initial running event without previous state', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: makeProgressResponse(validRequest, 'running'), explicitRetry: false }), 'INVALID_STATUS_TRANSITION') })
  it('accepts queued to running event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'queued', request: validRequest, response: makeProgressResponse(validRequest, 'running'), explicitRetry: false }).ok).toBe(true) })
  it('accepts running to draft_ready event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: makeDraftResponse(validRequest, { status: 'draft_ready' }), explicitRetry: false }).ok).toBe(true) })
  it('accepts running to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: validResponse, explicitRetry: false }).ok).toBe(true) })
  it('accepts draft_ready to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'draft_ready', request: validRequest, response: validResponse, explicitRetry: false }).ok).toBe(true) })
  it('accepts review_required to blocked event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'review_required', request: validRequest, response: makeFailureResponse(validRequest, 'blocked'), explicitRetry: false }).ok).toBe(true) })
  it('accepts retry_wait to queued with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'retry_wait', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: true }).ok).toBe(true) })
  it('accepts failed to queued with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'failed', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: true }).ok).toBe(true) })
  it('rejects retry_wait to queued without explicit retry', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'retry_wait', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'INVALID_STATUS_TRANSITION') })
  it('rejects running to queued', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'INVALID_STATUS_TRANSITION') })
  it('rejects an event with unknown previous state', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'unknown', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'UNKNOWN_STATE') })
  it('rejects an event with a published response', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'publishing', request: validRequest, response: { ...validResponse, status: 'published' }, explicitRetry: false }), 'UNKNOWN_STATE') })
  it('rejects an event with invalid request lineage', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: { ...validRequest, requestFingerprint: HASH_B }, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'REQUEST_FINGERPRINT_MISMATCH') })
  it('verifies a candidate response lineage', () => { const result = verifyGeoFlowLineage(validRequest, validResponse); expect(result.ok).toBe(true) })
  it('verifies a progress response lineage without content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeProgressResponse()).ok).toBe(true) })
  it('verifies a failure response lineage without content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeFailureResponse()).ok).toBe(true) })
  it('rejects candidate lineage with wrong article identity', () => { expectFailure(verifyGeoFlowLineage(validRequest, responseWith({ externalArticleKey: 'wrong', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'wrong' } })), 'IDENTITY_MISMATCH') })
  it('derives stable article identity from calendar entry and deliverable', () => { expect(deriveExternalArticleKey(validRequest)).toBe('article-101-303') })
  it('candidate identity matches request brief fingerprint', () => { expect(validResponse.draftIdentity.briefFingerprint).toBe(validRequest.briefFingerprint) })
  it('candidate identity does not use title as article identity', () => { expect(deriveExternalArticleKey(validRequest)).not.toContain(validRequest.brief.title) })
  it('response status remains candidate review_required', () => { expect(validResponse.status).toBe('review_required') })
  it('failure metadata contains only fixed code and retryable flag', () => { const failure = makeFailureResponse(); expect(Object.keys(failure.failure).sort()).toEqual(['code', 'retryable']) })
  it('progress metadata contains observedAt rather than completedAt', () => { const progress = makeProgressResponse(); expect('observedAt' in progress).toBe(true); expect('completedAt' in progress).toBe(false) })
  it('draft result contains content artifact rather than legacy top-level body fields', () => { expect('contentArtifact' in validResponse).toBe(true); expect('bodyMarkdown' in validResponse).toBe(false) })
  it('content artifact uses the fixed schema version', () => { expect(validResponse.contentArtifact.schemaVersion).toBe(CONTENT_ARTIFACT_SCHEMA_VERSION) })
})

describe('GEOFlow generation contract V1 — fixed HMAC envelope planner', () => {
  it('plans an envelope from request without bodyHash input', () => { const result = planSigningEnvelope(validEnvelopeInput); expect(result.ok).toBe(true); if (result.ok) expect(result.value.bodyHash).toMatch(/^[0-9a-f]{64}$/u) })
  it('computes bodyHash from canonical request bytes', () => { const canonical = canonicalizeContractValue(validRequest); const envelope = plannedEnvelope(); expect(canonical.ok).toBe(true); if (canonical.ok) expect(envelope.bodyHash).toBe(sha256(canonical.value)) })
  it('rejects caller-supplied bodyHash planner field', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, bodyHash: HASH_A }), 'UNKNOWN_FIELD') })
  it('rejects missing keyId planner field', () => { const input = { ...validEnvelopeInput } as Record<string, unknown>; delete input.keyId; expectFailure(planSigningEnvelope(input), 'UNKNOWN_FIELD') })
  it('uses fixed hmac-sha256 algorithm', () => { const envelope = plannedEnvelope(); expect(envelope.algorithm).toBe(SIGNING_ALGORITHM) })
  it('uses fixed POST method', () => { const envelope = plannedEnvelope(); expect(envelope.method).toBe(SIGNING_METHOD) })
  it('uses fixed generation-jobs path', () => { const envelope = plannedEnvelope(); expect(envelope.path).toBe(SIGNING_PATH) })
  it('uses caller-injected timestamp', () => { const envelope = plannedEnvelope({ timestamp: '2026-08-25T04:03:00+08:00' }); expect(envelope.timestamp).toBe('2026-08-24T20:03:00.000Z') })
  it('uses caller-injected nonce', () => { const envelope = plannedEnvelope({ nonce: 'Z'.repeat(32) }); expect(envelope.nonce).toBe('Z'.repeat(32)) })
  it('rejects a short nonce', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, nonce: 'short' }), 'INVALID_INPUT') })
  it('rejects a nonce with non-base64url punctuation', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, nonce: `${'N'.repeat(31)}!` }), 'INVALID_INPUT') })
  it('rejects an overlong nonce', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, nonce: 'N'.repeat(129) }), 'INVALID_INPUT') })
  it('rejects a keyId with secret-like punctuation', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, keyId: 'token=secret' }), 'INVALID_OPAQUE_IDENTIFIER') })
  it('canonical signing input starts with algorithm', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput.startsWith(`${SIGNING_ALGORITHM}\n`)).toBe(true) })
  it('canonical signing input includes method and path', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput.split('\n').slice(0, 3)).toEqual([SIGNING_ALGORITHM, SIGNING_METHOD, SIGNING_PATH]) })
  it('canonical signing input has fixed field count', () => { expect(plannedEnvelope().canonicalSigningInput.split('\n')).toHaveLength(13) })
  it('canonical signing input binds request fingerprint', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput).toContain(validRequest.requestFingerprint) })
  it('canonical signing input binds body hash', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput).toContain(envelope.bodyHash) })
  it('canonical signing input binds keyId', () => { const envelope = plannedEnvelope(); expect(envelope.canonicalSigningInput.endsWith('\nkey-1')).toBe(true) })
  it('canonical builder uses exact newline ordering', () => { const envelope = plannedEnvelope(); expect(buildCanonicalSigningInput(envelope as never)).toBe(envelope.canonicalSigningInput) })
  it('rejects an envelope extra field', () => { expectFailure(verifySigningEnvelope({ ...plannedEnvelope(), extra: true }, 'a'.repeat(64), signingContext()), 'UNKNOWN_FIELD') })
  it('rejects an envelope algorithm mutation', () => { expectFailure(verifySigningEnvelope({ ...plannedEnvelope(), algorithm: 'sha256' }, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an envelope method mutation', () => { expectFailure(verifySigningEnvelope({ ...plannedEnvelope(), method: 'PUT' }, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an envelope path mutation', () => { expectFailure(verifySigningEnvelope({ ...plannedEnvelope(), path: '/other' }, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an envelope request identity mutation', () => { const envelope = plannedEnvelope({ request: makeRequest({ requestId: 'req-002' }) }); expectFailure(verifySigningEnvelope(envelope, 'a'.repeat(64), signingContext()), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects a body hash mutation after canonical input update', () => { const envelope = plannedEnvelope(); const bodyHash = HASH_A; const mutated = { ...envelope, bodyHash, canonicalSigningInput: buildCanonicalSigningInput({ ...envelope, bodyHash }) }; expectFailure(verifySigningEnvelope(mutated, 'a'.repeat(64), signingContext()), 'CONTENT_HASH_MISMATCH') })
  it('accepts a valid synthetic signature verifier', () => { expect(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext()).ok).toBe(true) })
  it('rejects uppercase signature format', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'A'.repeat(64), signingContext()), 'INVALID_INPUT') })
  it('rejects short signature format', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(63), signingContext()), 'INVALID_INPUT') })
  it('rejects a signature with punctuation', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), `${'a'.repeat(63)}!`, signingContext()), 'INVALID_INPUT') })
  it('rejects a signature verifier mismatch', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => false })), 'IDENTITY_MISMATCH') })
  it('rejects a signature verifier exception', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ signatureVerifier: () => { throw new Error('signature') } })), 'IDENTITY_MISMATCH') })
  it('rejects sender context mismatch', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ expectedSender: 'other-sender' })), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects receiver context mismatch', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ expectedReceiver: 'other-receiver' })), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects keyId context mismatch', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ expectedKeyId: 'other-key' })), 'SIGNATURE_CONTEXT_MISMATCH') })
  it('rejects an expired timestamp', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ verificationTime: '2026-08-25T04:00:00Z', maxClockSkewSeconds: 60 })), 'SIGNATURE_EXPIRED') })
  it('rejects a future timestamp outside skew', () => { expectFailure(verifySigningEnvelope(plannedEnvelope({ timestamp: '2026-08-25T04:04:00Z' }), 'a'.repeat(64), signingContext({ verificationTime: '2026-08-25T04:02:00Z', maxClockSkewSeconds: 60 })), 'SIGNATURE_EXPIRED') })
  it('rejects a reused nonce', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceFreshnessVerifier: () => false })), 'NONCE_REPLAYED') })
  it('rejects a throwing nonce verifier', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ nonceFreshnessVerifier: () => { throw new Error('nonce') } })), 'NONCE_REPLAYED') })
  it('rejects maxClockSkewSeconds below one', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ maxClockSkewSeconds: 0 })), 'INVALID_INPUT') })
  it('rejects maxClockSkewSeconds above 300', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ maxClockSkewSeconds: 301 })), 'INVALID_INPUT') })
  it('rejects context unknown fields', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ extra: true })), 'UNKNOWN_FIELD') })
  it('rejects a malformed verification time', () => { expectFailure(verifySigningEnvelope(plannedEnvelope(), 'a'.repeat(64), signingContext({ verificationTime: 'tomorrow' })), 'INVALID_TIMESTAMP') })
  it('does not expose a secret field in envelope output', () => { expect('secret' in plannedEnvelope()).toBe(false) })
  it('does not expose authorization in envelope output', () => { expect('authorization' in plannedEnvelope()).toBe(false) })
  it('rejects a planner unknown field instead of ignoring it', () => { expectFailure(planSigningEnvelope({ ...validEnvelopeInput, secret: 'not-a-secret' }), 'UNKNOWN_FIELD') })
  it('accepts canonical signing input from fixed core', () => { const envelope = plannedEnvelope(); expect(buildCanonicalSigningInput(envelope as never).split('\n')[0]).toBe(SIGNING_ALGORITHM) })
})


describe('GEOFlow generation contract V1 — combined status events and lineage', () => {
  it('accepts initial queued event without previous state', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }).ok).toBe(true) })
  it('rejects initial running event without previous state', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: makeProgressResponse(validRequest, 'running'), explicitRetry: false }), 'INVALID_STATUS_TRANSITION') })
  it('accepts queued to running event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'queued', request: validRequest, response: makeProgressResponse(validRequest, 'running'), explicitRetry: false }).ok).toBe(true) })
  it('accepts running to draft_ready event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: makeDraftResponse(validRequest, { status: 'draft_ready' }), explicitRetry: false }).ok).toBe(true) })
  it('accepts running to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: validResponse, explicitRetry: false }).ok).toBe(true) })
  it('accepts draft_ready to review_required event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'draft_ready', request: validRequest, response: validResponse, explicitRetry: false }).ok).toBe(true) })
  it('accepts review_required to blocked event', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'review_required', request: validRequest, response: makeFailureResponse(validRequest, 'blocked'), explicitRetry: false }).ok).toBe(true) })
  it('accepts retry_wait to queued with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'retry_wait', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: true }).ok).toBe(true) })
  it('accepts failed to queued with explicit retry', () => { expect(validateGeoFlowStatusEventForStoredState({ previousStatus: 'failed', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: true }).ok).toBe(true) })
  it('rejects retry_wait to queued without explicit retry', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'retry_wait', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'INVALID_STATUS_TRANSITION') })
  it('rejects running to queued', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'INVALID_STATUS_TRANSITION') })
  it('rejects an event with unknown previous state', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'unknown', request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'UNKNOWN_STATE') })
  it('rejects an event with a published response', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: { ...validResponse, status: 'published' }, explicitRetry: false }), 'UNKNOWN_STATE') })
  it('rejects an event with request fingerprint mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: { ...validRequest, requestFingerprint: HASH_B }, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false }), 'REQUEST_FINGERPRINT_MISMATCH') })
  it('rejects an event with response request mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'queued', request: validRequest, response: { ...makeProgressResponse(validRequest, 'running'), requestId: 'other' }, explicitRetry: false }), 'IDENTITY_MISMATCH') })
  it('rejects an event with evidence mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: responseWith({ evidenceSnapshotHash: HASH_B }), explicitRetry: false }), 'EVIDENCE_SNAPSHOT_MISMATCH') })
  it('rejects an event with candidate article identity mismatch', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: responseWith({ externalArticleKey: 'other', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'other' } }), explicitRetry: false }), 'IDENTITY_MISMATCH') })
  it('rejects an event with an applied rule outside selection', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: responseWith({ appliedRuleIds: ['not-selected'] }), explicitRetry: false }), 'APPLIED_RULE_OUTSIDE_SELECTION') })
  it('rejects a status event unknown field', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: false, extra: true }), 'UNKNOWN_FIELD') })
  it('rejects a status event null response', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: null, explicitRetry: false }), 'INVALID_INPUT') })
  it('rejects a status event nonboolean retry flag', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: makeProgressResponse(validRequest, 'queued'), explicitRetry: 'yes' }), 'INVALID_INPUT') })
  it('accepts a verified candidate lineage', () => { const result = verifyGeoFlowLineage(validRequest, validResponse); expect(result.ok).toBe(true) })
  it('accepts progress lineage without a content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeProgressResponse()).ok).toBe(true) })
  it('accepts failure lineage without a content artifact', () => { expect(verifyGeoFlowLineage(validRequest, makeFailureResponse()).ok).toBe(true) })
  it('rejects candidate lineage with wrong external article key', () => { expectFailure(verifyGeoFlowLineage(validRequest, responseWith({ externalArticleKey: 'other', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: 'other' } })), 'IDENTITY_MISMATCH') })
  it('derives the stable article key from server IDs', () => { expect(deriveExternalArticleKey(validRequest)).toBe('article-101-303') })
  it('does not derive article identity from brief title', () => { expect(deriveExternalArticleKey(validRequest)).not.toContain(validRequest.brief.title) })
  it('keeps candidate status review_required', () => { expect(validResponse.status).toBe('review_required') })
  it('keeps failure state separate from draft result', () => { expect('failure' in makeFailureResponse()).toBe(true); expect('contentArtifact' in makeFailureResponse()).toBe(false) })
  it('keeps progress state separate from draft result', () => { expect('observedAt' in makeProgressResponse()).toBe(true); expect('contentArtifact' in makeProgressResponse()).toBe(false) })
  it('keeps retry state separate from failure state', () => { expect('retry' in makeRetryResponse()).toBe(true); expect('failure' in makeRetryResponse()).toBe(false) })
  it('requires fixed candidate artifact schema version', () => { expect(validResponse.contentArtifact.schemaVersion).toBe(CONTENT_ARTIFACT_SCHEMA_VERSION) })
  it('preserves exact candidate body newline', () => { expect(validResponse.contentArtifact.bodyMarkdown).toBe(BODY_MARKDOWN) })
  it('preserves exact candidate body hash', () => { expect(validResponse.contentArtifact.bodyHash).toBe(BODY_HASH) })
  it('uses lowercase candidate body hash', () => { expect(validResponse.contentArtifact.bodyHash).toMatch(/^[0-9a-f]{64}$/u) })
  it('uses lowercase chunk hash', () => { expect(validRequest.evidenceChunks[0]?.chunkHash).toMatch(/^[0-9a-f]{64}$/u) })
  it('lineage success retains validated request evidence for correlation', () => { const result = verifyGeoFlowLineage(validRequest, validResponse); expect(result.ok).toBe(true); if (result.ok) expect(result.value.request.evidenceChunks).toHaveLength(1) })
  it('does not expose stack text in event failures', () => { const result = validateGeoFlowStatusEventForStoredState({ previousStatus: null, request: validRequest, response: { ...makeProgressResponse(validRequest, 'queued'), observedAt: 'invalid' }, explicitRetry: false }); expectFailure(result, 'INVALID_TIMESTAMP'); expect(JSON.stringify(result)).not.toContain('Error') })
  it('rejects terminal delivery vocabulary in a response', () => { expectFailure(validateGeoFlowResponse({ ...validResponse, status: 'delivered' }, validRequest), 'UNKNOWN_STATE') })
  it('rejects terminal delivery vocabulary in a status event', () => { expectFailure(validateGeoFlowStatusEventForStoredState({ previousStatus: 'running', request: validRequest, response: { ...validResponse, status: 'delivered' }, explicitRetry: false }), 'UNKNOWN_STATE') })
  it('rejects a response with missing external project identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalProjectKey: '' }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('rejects a response with missing external task identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalTaskKey: '' }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('rejects a response with missing external job identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalJobKey: '' }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
  it('rejects a response with missing external article identity', () => { expectFailure(validateGeoFlowResponse(responseWith({ externalArticleKey: '', draftIdentity: { ...validResponse.draftIdentity, externalArticleKey: '' } }), validRequest), 'INVALID_OPAQUE_IDENTIFIER') })
})
